// Партия 1 синхронизации справочник -> календарь: закрывает пустой блок
// «Календарь работ по культуре» у трёх регион-специфичных культур, где .md
// (паспорт + regions_notes) утверждает, что культура в регионе выращивается,
// а строк в garden-data.xlsx для этого региона нет.
//
//   voylochnaya-vishnya — средняя полоса (укрывная/холмиковая культура), юг
//   persik              — средняя полоса (пристенная/укрывная культура)
//   klyukva             — средняя полоса (основной регион по .md), + Урал-Сибирь, юг
//
// Формулировки, сроки и препараты согласованы с docs/plants-src/<id>.md —
// правило «Синхронизация справочника и календаря» в Garden/CLAUDE.md.
//
// Источники (веб-поиск, сентябрь 2026):
// - Войлочная вишня, подопревание корневой шейки, посадка на холм, обрезка
//   побегов >60 см на 1/3, прищипка за 2-3 недели до заморозков, отгребание
//   снега от шейки в оттепели:
//   supersadovnik.ru/plant/vishnya-vojlochnaya-1391,
//   greeninfo.ru/fruits/cerasus_tomentosa/vishnya-voilochnaya-posadka-obrezka-sorta_art.html,
//   sibsad-pitomnik.ru/blog/plodovyj-sad/posadka-obrezka-vojlochnoj-vishni
// - Войлочная вишня, монилиоз через 10-14 дней после цветения, обработки до и
//   после цветения (1%-я бордоская, «Хорус», «Скор»), осенью по опавшему листу:
//   fertilizerdaily.ru/20220422-kak-lechit-monilioz-vishni,
//   stroy-podskazka.ru/vishnya/bolezni/monilioz
// - Персик в средней полосе: штамб 30-40 см / кустовая-пристенная форма,
//   обработка от курчавости по «зелёному конусу» 3%-й бордоской, с середины
//   лета убрать азот -> фосфор-калий, укрытие до первых заморозков (спанбонд
//   2-3 слоя), опасность не морозы а выпревание:
//   antonovsad.ru/kak-vyrastit-persik-v-sredney-polose-4221,
//   ferma.expert/rasteniya/derevya/persiki/ukrytie,
//   zelynyjsad.info/stati/kak-ukryvat-persik-na-zimu-v-sredney-polose
// - Клюква крупноплодная: торфогряда pH 3,5-5 с бортиками, посадка во 2-й
//   половине апреля при оттаивании на 8-10 см, обрезка/прореживание в мае
//   (первые 3 года), подкормка вересковым удобрением середина августа +
//   середина октября, пескование торф+песок слоем 1,5-3 см раз в 3-4 года,
//   укрытие лапником/спанбондом, послойный залив водой на зиму:
//   supersadovnik.ru/plant/klyukva-krupnoplodnaya-1364,
//   rastenievod.com/klyukva.html,
//   antonovsad.ru/vyrashchivanie-klyukvy-v-sadu-sorta-posadka-i-uhod-2302

const path = require('path');
const XLSX = require('xlsx');

const XLSX_PATH = path.resolve(__dirname, '..', '..', 'garden-data.xlsx');
const wb = XLSX.readFile(XLSX_PATH);
const calRows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar']);

const MONTH_IDS = ['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentyabr','oktyabr','noyabr','dekabr'];
const MONTH_NAMES = ['ЯНВАРЬ','ФЕВРАЛЬ','МАРТ','АПРЕЛЬ','МАЙ','ИЮНЬ','ИЮЛЬ','АВГУСТ','СЕНТЯБРЬ','ОКТЯБРЬ','НОЯБРЬ','ДЕКАБРЬ'];

function row(region, monthIdx, workType, plants, text, source, detail) {
  return {
    region,
    month: MONTH_IDS[monthIdx],
    monthName: MONTH_NAMES[monthIdx],
    workType,
    category: 'sad',
    plants: plants.join(','),
    growMethod: 'grunt',
    text,
    detail: detail || '',
    source: source || '',
  };
}

const S_VV = 'supersadovnik.ru/plant/vishnya-vojlochnaya-1391; fertilizerdaily.ru/20220422-kak-lechit-monilioz-vishni; sibsad-pitomnik.ru/blog/plodovyj-sad/posadka-obrezka-vojlochnoj-vishni';
const S_PE = 'antonovsad.ru/kak-vyrastit-persik-v-sredney-polose-4221; ferma.expert/rasteniya/derevya/persiki/ukrytie; zelynyjsad.info/stati/kak-ukryvat-persik-na-zimu-v-sredney-polose';
